// Loader for the Rust `rewriter` crate's wasm-bindgen build. Mirrors
// node-wasm/loader.ts's lazy-singleton pattern, but instantiates through
// wasm-bindgen's own glue (`initSync`) instead of a hand-rolled
// WebAssembly.Instance: unlike node-worker.wasm (built with
// -sSTANDALONE_WASM=1), wasm-bindgen's `--target web` output isn't standalone
// — it needs the imports object its own glue builds.

// @ts-ignore — generated by prepare-node.js, lives outside the TS rootDir
import rewriterWasmBase64 from "../../../node_core/wasm-build/rewriter.wasm.js";
// @ts-ignore — generated by prepare-node.js, lives outside the TS rootDir
import { Rewriter, initSync } from "../../../node_core/wasm-build/rewriter.js";

export type { Rewriter };

function decodeBase64(base64: string): Uint8Array {
	if (typeof atob === "function") {
		return Uint8Array.from(atob(base64), (char) => char.charCodeAt(0));
	}
	if (typeof Buffer !== "undefined") {
		return Uint8Array.from(Buffer.from(base64, "base64"));
	}
	throw new Error("No base64 decoder available for rewriter wasm");
}

let rewriter: Rewriter | null = null;

export function getRewriter(): Rewriter {
	if (rewriter) return rewriter;

	initSync({ module: decodeBase64(rewriterWasmBase64) });
	rewriter = new Rewriter();
	return rewriter;
}
